"""ball_eval_st.py on a Kaggle GPU: the old and the new ball detector on the SoccerTrack v2 benchmark test matches'
saved crops (M7 128057, M9 132831; dataset soccertrack-test-crops). No competition data."""
import os
import subprocess
import sys
import tarfile
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "ultralytics>=8.4"], check=False)
import glob
ST = os.path.dirname(sorted(glob.glob("/kaggle/input/**/events_feet.csv", recursive=True))[0])   # unpacked by Kaggle
os.makedirs("/kaggle/tmp/w", exist_ok=True)
for name in ("ball_soccernet_k.pt", "ball_st_k3.pt"):
    src = sorted(glob.glob(f"/kaggle/input/**/{name}", recursive=True))
    if src:
        os.symlink(src[0], f"/kaggle/tmp/w/{name}")
os.makedirs("/kaggle/tmp/code", exist_ok=True)
open("/kaggle/tmp/code/ball_pseudo_select.py", "w").write('"""Ball boxes on SoccerTrack v2 from our detector\'s sightings at the acting players\' feet (ball_pseudo_st.py), and the\ntraining images made from them. No person decides any box.\n\nPer kick or dribble event: a sighting in the event frame within R_FEET actor-box heights of the actor\'s feet is the\nball if it is confident (conf >= CONF_ALONE) or if, in at least SUPPORT of the NEAR frames either side, there is a\nsighting no farther from it than STEP box heights per frame of offset (the ball moves at most about 30 m/s, a box\nheight is about 1.8 m) with that sighting at conf >= CONF_CHAIN. The best such sighting (most support, then highest\nconfidence) and its supporting sightings in the other frames become boxes. Each labelled crop becomes a training image as\nbuild_soccernet_crops.py makes them: the 320 px crop enlarged 2x, the box as COCO class 32 ("sports ball").\n\nThe benchmark test matches (M7 128057, M9 132831) are never written as training images (ball_eval_st.py scores on\nthem). Usage: python ball_pseudo_select.py [--out=crops_st] [--native]   -> data/open/soccertrack/<out>/{images,labels}\n"""\nimport os\nimport shutil\nimport sys\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\nimport pandas as pd\n\nROOT = Path(os.environ.get("ST_ROOT", Path(__file__).resolve().parent.parent / "data" / "open" / "soccertrack"))\nTEST = ("128057", "132831")\nR_FEET, STEP, SUPPORT = 2.0, 0.7, 2\nCONF_ALONE, CONF_CHAIN = 0.5, 0.1\nCROP, SCALE = 320, 2\nNATIVE = "--native" in sys.argv   # keep the 320 px crops as they are (enlarged 2x where they are trained)\n\n\ndef select(d):\n    """Rows of d (one half\'s sightings) that are the ball, one per (event, frame offset) at most."""\n    keep = []\n    for (frame, pid), ev in d.groupby(["frame", "player_id"]):\n        h = float(ev.box_h.iloc[0])\n        at = ev[(ev.offset == 0) & (ev.dist <= R_FEET * h)]\n        best = None\n        for _, c in at.iterrows():\n            sup = []\n            for o in sorted(set(ev.offset) - {0}):\n                nb = ev[ev.offset == o]\n                if not len(nb):\n                    continue\n                gap = np.hypot(nb.px - c.px, nb.py - c.py)\n                ok = nb[(gap <= STEP * h * abs(o)) & (nb.conf >= CONF_CHAIN)]\n                if len(ok):\n                    sup.append(ok.loc[np.hypot(ok.px - c.px, ok.py - c.py).idxmin()])\n            if c.conf >= CONF_ALONE or (len(sup) >= SUPPORT and c.conf >= CONF_CHAIN):\n                key = (len(sup), c.conf)\n                if best is None or key > best[0]:\n                    best = (key, c, sup)\n        if best is not None:\n            keep.append(best[1])\n            keep.extend(best[2])\n    return pd.DataFrame(keep)\n\n\ndef write(rows, half_dir, out, prefix):\n    for _, r in rows.iterrows():\n        img = cv2.imread(str(half_dir / "crops" / f"{r.crop}.jpg"))\n        if img is None:\n            continue\n        big = img if NATIVE else cv2.resize(img, (CROP * SCALE, CROP * SCALE), interpolation=cv2.INTER_CUBIC)\n        name = f"{prefix}_{r.crop}"\n        cv2.imwrite(str(out / "images" / f"{name}.jpg"), big, [cv2.IMWRITE_JPEG_QUALITY, 92])\n        cx, cy, s = (r.px - r.x0) / CROP, (r.py - r.y0) / CROP, max(float(r["size"]), 4.0) / CROP\n        (out / "labels" / f"{name}.txt").write_text(f"32 {cx:.5f} {cy:.5f} {s:.5f} {s:.5f}\\n")\n\n\ndef main():\n    out = ROOT / next((a.split("=", 1)[1] for a in sys.argv if a.startswith("--out=")), "crops_st")\n    shutil.rmtree(out, ignore_errors=True)\n    (out / "images").mkdir(parents=True)\n    (out / "labels").mkdir()\n    total = {"events": 0, "labelled events": 0, "images": 0}\n    for half_dir in sorted((ROOT / "pseudo").glob("*_*")):\n        if not (half_dir / "dets.csv").exists():\n            continue\n        match, half = half_dir.name.split("_")\n        d = pd.read_csv(half_dir / "dets.csv", dtype={"player_id": str})\n        n_events = len(list((half_dir / "crops").glob("*_+0.jpg")))\n        rows = select(d)\n        labelled = rows[rows.offset == 0] if len(rows) else rows\n        print(f"{match} {half}: {n_events} events, ball found at {len(labelled)} ({len(labelled) / max(n_events, 1):.0%}), "\n              f"{len(rows)} boxes with the neighbouring frames" + ("  [test match: not written]" if match in TEST else ""),\n              flush=True)\n        if match in TEST:\n            continue\n        write(rows, half_dir, out, half_dir.name)\n        total["events"] += n_events\n        total["labelled events"] += len(labelled)\n        total["images"] += len(rows)\n    print(f"training images: {total}")\n\n\nif __name__ == "__main__":\n    main()\n')
open("/kaggle/tmp/code/ball_eval_st.py", "w").write('"""A ball detector on the SoccerTrack v2 benchmark test matches (M7 128057, M9 132831), never trained on: every saved\ncrop around a kick or dribble event (ball_pseudo_st.py, the event frame and NEAR frames either side) goes through the\ndetector as on our match (enlarged 2x, conf >= 0.05). Per detector:\n  found at the feet   events whose event frame has a sighting at conf >= 0.5 within R_FEET box heights of the feet\n  found by the rule   events where ball_pseudo_select.py\'s rule (sightings agreeing over the neighbouring frames) finds it\n  far confident       sightings at conf >= 0.5 more than FAR box heights from the feet, per 1,000 crops (the ball is at\n                      the feet in these frames, so nearly all of them are false)\nUsage: python ball_eval_st.py ball_soccernet_k.pt [other weights in models/weights ...]\n"""\nimport os\nimport sys\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\nimport pandas as pd\n\nimport ball_pseudo_select as sel\n\nos.environ.setdefault("PYTORCH_ENABLE_MPS_FALLBACK", "1")\nWEIGHTS = Path(os.environ.get("WEIGHTS_DIR", Path(__file__).resolve().parent / "models" / "weights"))\nDEVICE = os.environ.get("DEVICE", "mps")\nFAR = 4.0\n\n\ndef crops():\n    ev = pd.read_csv(sel.ROOT / "events_feet.csv", dtype={"match": str, "player_id": str})\n    ev = ev[ev.match.isin(sel.TEST)]\n    rows = []\n    for _, r in ev.iterrows():\n        d = sel.ROOT / "pseudo" / f"{r.match}_{r.half}" / "crops"\n        if not d.exists():\n            continue\n        fx, fy = r.x + r.w / 2, r.y + r.h\n        x0 = int(np.clip(fx - sel.CROP / 2, 0, r.width - sel.CROP))\n        y0 = int(np.clip(fy - sel.CROP / 2, 0, r.height - sel.CROP))\n        for o in range(-2, 3):\n            p = d / f"{int(r.frame):06d}_{r.player_id}_{o:+d}.jpg"\n            if p.exists():\n                rows.append((f"{r.match}_{r.half}", int(r.frame), o, r.player_id, str(p), x0, y0, fx, fy, r.w, r.h))\n    return pd.DataFrame(rows, columns=["half", "frame", "offset", "player_id", "path", "x0", "y0", "feet_x", "feet_y",\n                                       "box_w", "box_h"])\n\n\ndef detect(model, table):\n    out = []\n    for _, c in table.iterrows():\n        big = cv2.resize(cv2.imread(c.path), (sel.CROP * sel.SCALE,) * 2, interpolation=cv2.INTER_CUBIC)\n        r = model.predict(big, imgsz=sel.CROP * sel.SCALE, conf=0.05, classes=[32], device=DEVICE, verbose=False)[0]\n        for (x1, y1, x2, y2), conf in zip(r.boxes.xyxy.cpu().numpy(), r.boxes.conf.cpu().numpy()):\n            px, py = c.x0 + (x1 + x2) / 2 / sel.SCALE, c.y0 + (y1 + y2) / 2 / sel.SCALE\n            out.append((c.half, c.frame, c.offset, c.player_id, float(conf), px, py, max(x2 - x1, y2 - y1) / sel.SCALE,\n                        c.feet_x, c.feet_y, c.box_h, float(np.hypot(px - c.feet_x, py - c.feet_y))))\n    return pd.DataFrame(out, columns=["half", "frame", "offset", "player_id", "conf", "px", "py", "size", "feet_x",\n                                      "feet_y", "box_h", "dist"])\n\n\ndef main():\n    from ultralytics import YOLO\n    table = crops()\n    events = table[table.offset == 0]\n    print(f"test matches: {len(events)} events, {len(table)} crops", flush=True)\n    for w in sys.argv[1:]:\n        d = detect(YOLO(str(WEIGHTS / w)), table)\n        ev0 = d[d.offset == 0]\n        feet = ev0[(ev0.conf >= 0.5) & (ev0.dist <= sel.R_FEET * ev0.box_h)].groupby(["half", "frame", "player_id"]).size()\n        found_rule = 0\n        for _, g in d.groupby("half"):\n            s = sel.select(g)\n            found_rule += int((s.offset == 0).sum()) if len(s) else 0\n        far = d[(d.conf >= 0.5) & (d.dist > FAR * d.box_h)]\n        print(f"{w:28s} found at the feet {len(feet) / len(events):6.1%}   found by the rule {found_rule / len(events):6.1%}   "\n              f"far confident per 1000 crops {1000 * len(far) / len(table):5.1f}", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n')
env = dict(os.environ, ST_ROOT=ST, WEIGHTS_DIR="/kaggle/tmp/w", DEVICE="0")
subprocess.run([sys.executable, "ball_eval_st.py", *sorted(os.listdir("/kaggle/tmp/w"))], cwd="/kaggle/tmp/code", env=env, check=True)
